// VCS coverage exclude_file
module ram_512x13(
  input  [8:0]  R0_addr,
  input         R0_en,
                R0_clk,
  output [12:0] R0_data,
  input  [8:0]  W0_addr,
  input         W0_en,
                W0_clk,
  input  [12:0] W0_data
);

  reg [12:0] Memory[0:511];
  always @(posedge W0_clk) begin
    if (W0_en & 1'h1)
      Memory[W0_addr] <= W0_data;
  end // always @(posedge)
  assign R0_data = R0_en ? Memory[R0_addr] : 13'bx;
endmodule

module Queue512_BundleMap(
  input        clock,
               reset,
  output       io_enq_ready,
  input        io_enq_valid,
  input  [3:0] io_enq_bits_tl_state_size,
  input  [8:0] io_enq_bits_tl_state_source,
  input        io_deq_ready,
  output       io_deq_valid,
  output [3:0] io_deq_bits_tl_state_size,
  output [8:0] io_deq_bits_tl_state_source
);

  wire [12:0] _ram_ext_R0_data;
  reg  [8:0]  enq_ptr_value;
  reg  [8:0]  deq_ptr_value;
  reg         maybe_full;
  wire        ptr_match = enq_ptr_value == deq_ptr_value;
  wire        empty = ptr_match & ~maybe_full;
  wire        full = ptr_match & maybe_full;
  wire        do_enq = ~full & io_enq_valid;
  always @(posedge clock) begin
    if (reset) begin
      enq_ptr_value <= 9'h0;
      deq_ptr_value <= 9'h0;
      maybe_full <= 1'h0;
    end
    else begin
      automatic logic do_deq = io_deq_ready & ~empty;
      if (do_enq)
        enq_ptr_value <= enq_ptr_value + 9'h1;
      if (do_deq)
        deq_ptr_value <= deq_ptr_value + 9'h1;
      if (~(do_enq == do_deq))
        maybe_full <= do_enq;
    end
  end // always @(posedge)
  ram_512x13 ram_ext (
    .R0_addr (deq_ptr_value),
    .R0_en   (1'h1),
    .R0_clk  (clock),
    .R0_data (_ram_ext_R0_data),
    .W0_addr (enq_ptr_value),
    .W0_en   (do_enq),
    .W0_clk  (clock),
    .W0_data ({io_enq_bits_tl_state_source, io_enq_bits_tl_state_size})
  );
  assign io_enq_ready = ~full;
  assign io_deq_valid = ~empty;
  assign io_deq_bits_tl_state_size = _ram_ext_R0_data[3:0];
  assign io_deq_bits_tl_state_source = _ram_ext_R0_data[12:4];
endmodule

