module FixedBankReadAdmission(
  input  clock,
         reset,
         io_offer,
         io_room,
         io_bankReady_0,
         io_bankReady_1,
         io_bankReady_2,
         io_bankReady_3,
         io_bankReady_4,
         io_bankReady_5,
         io_bankReady_6,
         io_bankReady_7,
         io_bankReady_8,
         io_bankReady_9,
         io_bankReady_10,
         io_bankReady_11,
         io_bankReady_12,
         io_bankReady_13,
         io_bankReady_14,
         io_bankReady_15,
  output io_bankValid_0,
         io_bankValid_1,
         io_bankValid_2,
         io_bankValid_3,
         io_bankValid_4,
         io_bankValid_5,
         io_bankValid_6,
         io_bankValid_7,
         io_bankValid_8,
         io_bankValid_9,
         io_bankValid_10,
         io_bankValid_11,
         io_bankValid_12,
         io_bankValid_13,
         io_bankValid_14,
         io_bankValid_15,
         io_admit,
         io_pending
);

  reg  [15:0] remaining;
  reg         pending;
  wire        io_admit_0 = io_offer & io_room & ~pending;
  wire [15:0] needed = pending ? remaining : 16'hFFFF;
  wire        issue = pending | io_admit_0;
  wire        io_bankValid_0_0 = issue & needed[0];
  wire        io_bankValid_1_0 = issue & needed[1];
  wire        io_bankValid_2_0 = issue & needed[2];
  wire        io_bankValid_3_0 = issue & needed[3];
  wire        io_bankValid_4_0 = issue & needed[4];
  wire        io_bankValid_5_0 = issue & needed[5];
  wire        io_bankValid_6_0 = issue & needed[6];
  wire        io_bankValid_7_0 = issue & needed[7];
  wire        io_bankValid_8_0 = issue & needed[8];
  wire        io_bankValid_9_0 = issue & needed[9];
  wire        io_bankValid_10_0 = issue & needed[10];
  wire        io_bankValid_11_0 = issue & needed[11];
  wire        io_bankValid_12_0 = issue & needed[12];
  wire        io_bankValid_13_0 = issue & needed[13];
  wire        io_bankValid_14_0 = issue & needed[14];
  wire        io_bankValid_15_0 = issue & needed[15];
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      if (~reset & pending != (|remaining)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: cached pending differs from remaining banks\n    at FixedBankReadAdmission.scala:27 assert(status === remaining.orR, \"cached pending differs from remaining banks\")\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (pending & ~reset & io_admit_0) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: cannot admit a row before all its bank reads issue\n    at FixedBankReadAdmission.scala:42 when(io.pending) { assert(!io.admit, \"cannot admit a row before all its bank reads issue\") }\n");
        if (`STOP_COND_)
          $fatal;
      end
    end // always @(posedge)
  `endif // not def SYNTHESIS
  always @(posedge clock) begin
    if (reset) begin
      remaining <= 16'h0;
      pending <= 1'h0;
    end
    else if (issue) begin
      automatic logic [15:0] left =
        needed
        & ~{io_bankValid_15_0 & io_bankReady_15,
            io_bankValid_14_0 & io_bankReady_14,
            io_bankValid_13_0 & io_bankReady_13,
            io_bankValid_12_0 & io_bankReady_12,
            io_bankValid_11_0 & io_bankReady_11,
            io_bankValid_10_0 & io_bankReady_10,
            io_bankValid_9_0 & io_bankReady_9,
            io_bankValid_8_0 & io_bankReady_8,
            io_bankValid_7_0 & io_bankReady_7,
            io_bankValid_6_0 & io_bankReady_6,
            io_bankValid_5_0 & io_bankReady_5,
            io_bankValid_4_0 & io_bankReady_4,
            io_bankValid_3_0 & io_bankReady_3,
            io_bankValid_2_0 & io_bankReady_2,
            io_bankValid_1_0 & io_bankReady_1,
            io_bankValid_0_0 & io_bankReady_0};
      remaining <= left;
      pending <= |left;
    end
  end // always @(posedge)
  assign io_bankValid_0 = io_bankValid_0_0;
  assign io_bankValid_1 = io_bankValid_1_0;
  assign io_bankValid_2 = io_bankValid_2_0;
  assign io_bankValid_3 = io_bankValid_3_0;
  assign io_bankValid_4 = io_bankValid_4_0;
  assign io_bankValid_5 = io_bankValid_5_0;
  assign io_bankValid_6 = io_bankValid_6_0;
  assign io_bankValid_7 = io_bankValid_7_0;
  assign io_bankValid_8 = io_bankValid_8_0;
  assign io_bankValid_9 = io_bankValid_9_0;
  assign io_bankValid_10 = io_bankValid_10_0;
  assign io_bankValid_11 = io_bankValid_11_0;
  assign io_bankValid_12 = io_bankValid_12_0;
  assign io_bankValid_13 = io_bankValid_13_0;
  assign io_bankValid_14 = io_bankValid_14_0;
  assign io_bankValid_15 = io_bankValid_15_0;
  assign io_admit = io_admit_0;
  assign io_pending = pending;
