    automatic logic       _GEN_4;
    automatic logic       _GEN_5;
    automatic logic       _GEN_6;
    _remaining_T = {hit_2_0 & _take_1_2_T, hit_1_0 & _take_1_1_T, hit_0 & _take_1_0_T};
    _remaining_T_2 = {hit_2_1 & _take_1_2_T, hit_1_1 & _take_1_1_T, hit_1 & _take_1_0_T};
