  reg  [3:0]   pending_1;
  wire         io_allocate_ready_0 =
    {valid_1, valid_0} != 2'h3
    & ~(valid_0 & key_0 == io_allocate_bits | valid_1 & key_1 == io_allocate_bits);
  wire         _hit_T_30 = valid_0 & available_0;
  wire         hit_0 = _hit_T_30 & pending_0[0] & key_0 == io_request_0_bits;
  wire         _hit_T_35 = valid_1 & available_1;
  wire         hit_1 = _hit_T_35 & pending_1[0] & key_1 == io_request_0_bits;
  wire [1:0]   _io_request_0_ready_T = {hit_1, hit_0};
  wire         hit_1_0 = _hit_T_30 & pending_0[1] & key_0 == io_request_1_bits;
  wire         hit_1_1 = _hit_T_35 & pending_1[1] & key_1 == io_request_1_bits;
  wire [1:0]   _io_request_1_ready_T = {hit_1_1, hit_1_0};
  wire         hit_2_0 = _hit_T_30 & pending_0[2] & key_0 == io_request_2_bits;
