  wire         hit_3_1 = _hit_T_35 & pending_1[3] & key_1 == io_request_3_bits;
  wire [1:0]   _io_request_3_ready_T = {hit_3_1, hit_3_0};
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      automatic logic [1:0] _GEN = {1'h0, hit_0} + {1'h0, hit_1};
      automatic logic [1:0] _GEN_0 = {1'h0, hit_1_0} + {1'h0, hit_1_1};
      automatic logic [1:0] _GEN_1 = {1'h0, hit_2_0} + {1'h0, hit_2_1};
      automatic logic [1:0] _GEN_2 = {1'h0, hit_3_0} + {1'h0, hit_3_1};
      if (~reset & _GEN[1]) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed\n    at GramOperandBuffer.scala:39 assert(PopCount(hit) <= 1.U)\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (~reset & _GEN_0[1]) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed\n    at GramOperandBuffer.scala:39 assert(PopCount(hit) <= 1.U)\n");
        if (`STOP_COND_)
          $fatal;
