module Queue4_UInt8(
  input        clock,
               reset,
  output       io_enq_ready,
  input        io_enq_valid,
  input  [7:0] io_enq_bits,
  input        io_deq_ready,
  output       io_deq_valid,
  output [7:0] io_deq_bits
);

  reg  [1:0] enq_ptr_value;
  reg  [1:0] deq_ptr_value;
  reg        maybe_full;
  wire       ptr_match = enq_ptr_value == deq_ptr_value;
  wire       empty = ptr_match & ~maybe_full;
  wire       full = ptr_match & maybe_full;
  wire       do_enq = ~full & io_enq_valid;
  always @(posedge clock) begin
    if (reset) begin
      enq_ptr_value <= 2'h0;
      deq_ptr_value <= 2'h0;
      maybe_full <= 1'h0;
    end
    else begin
      automatic logic do_deq = io_deq_ready & ~empty;
      if (do_enq)
        enq_ptr_value <= enq_ptr_value + 2'h1;
      if (do_deq)
        deq_ptr_value <= deq_ptr_value + 2'h1;
      if (~(do_enq == do_deq))
        maybe_full <= do_enq;
    end
  end // always @(posedge)
  ram_4x8 ram_ext (
    .R0_addr (deq_ptr_value),
    .R0_en   (1'h1),
    .R0_clk  (clock),
    .R0_data (io_deq_bits),
    .W0_addr (enq_ptr_value),
    .W0_en   (do_enq),
    .W0_clk  (clock),
    .W0_data (io_enq_bits)
  );
  assign io_enq_ready = ~full;
  assign io_deq_valid = ~empty;
endmodule

module RegisteredTagQueue(
  input           clock,
                  reset,
  output          io_enq_ready,
  input           io_enq_valid,
  input  [2088:0] io_enq_bits,
  input           io_deq_ready,
  output          io_deq_valid,
  output [2088:0] io_deq_bits
);

  reg [2088:0] tail;
  reg [2088:0] head;
  reg [1:0]    occupancy;
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      if (~reset & (&occupancy)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed\n    at RegisteredTagQueue.scala:67 assert(occupancy <= entries.U)\n");
        if (`STOP_COND_)
          $fatal;
      end
    end // always @(posedge)
  `endif // not def SYNTHESIS
  always @(posedge clock) begin
    automatic logic put;
    automatic logic take;
    automatic logic directHead;
    put = ~(occupancy[1]) & io_enq_valid;
    take = io_deq_ready & (|occupancy);
    directHead = put & (occupancy == 2'h0 | take & occupancy == 2'h1);
    if (put & ~directHead)
      tail <= io_enq_bits;
    if (directHead)
      head <= io_enq_bits;
    else if (take & occupancy[1])
      head <= tail;
    if (reset)
      occupancy <= 2'h0;
    else if (~(put == take))
      occupancy <= put ? occupancy + 2'h1 : occupancy - 2'h1;
  end // always @(posedge)
  assign io_enq_ready = ~(occupancy[1]);
  assign io_deq_valid = |occupancy;
  assign io_deq_bits = head;
endmodule

