     io_read_1_ready & io_read_1_valid_0,
     io_read_0_ready & io_read_0_valid_0};
  wire        returned =
    (~(_tags_io_deq_bits[10]) | io_response_0_valid)
    & (~(_tags_io_deq_bits[11]) | io_response_1_valid)
    & (~(_tags_io_deq_bits[12]) | io_response_2_valid)
    & (~(_tags_io_deq_bits[13]) | io_response_3_valid)
    & (~(_tags_io_deq_bits[14]) | io_response_4_valid)
