    & (~(_tags_io_deq_bits[23]) | io_response_13_valid)
    & (~(_tags_io_deq_bits[24]) | io_response_14_valid)
    & (~(_tags_io_deq_bits[25]) | io_response_15_valid);
  wire        results_io_enq_valid = _tags_io_deq_valid & returned;
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      automatic logic [4:0] _GEN = {1'h0, reserved} + {1'h0, _results_io_count};
      automatic logic       _GEN_0 = partial & ~reset;
      if (~reset & {1'h0, outstanding} != _GEN) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: reader occupancy lost a reserved row\n    at BankVectorReader.scala:48 assert(count === (reserved +& results.io.count), \"reader occupancy lost a reserved row\")\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (~partial & (|acceptedBanks) & ~reset & ~tags_io_enq_valid) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: bank read without a reserved vector\n    at BankVectorReader.scala:97 assert(io.request.fire, \"bank read without a reserved vector\")\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (_GEN_0 & ~((|remaining) & (|reserved))) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: partial vector lost its reservation\n    at BankVectorReader.scala:100 assert(remaining.orR && reserved =/= 0.U, \"partial vector lost its reservation\")\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (_GEN_0 & (|(acceptedBanks & ~remaining))) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: bank read accepted twice\n    at BankVectorReader.scala:101 assert((acceptedBanks & ~remaining) === 0.U, \"bank read accepted twice\")\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (~reset & _GEN > 5'h8) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: vector result capacity exceeded\n    at BankVectorReader.scala:123 assert((reserved +& results.io.count) <= 8.U, \"vector result capacity exceeded\")\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (results_io_enq_valid & ~reset & ~(_results_io_enq_ready & (|reserved))) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: unreserved vector result\n    at BankVectorReader.scala:125 assert(results.io.enq.ready && reserved =/= 0.U, \"unreserved vector result\")\n");
        if (`STOP_COND_)
