module Queue2_NPackedBlock(
  input         clock,
                reset,
  output        io_enq_ready,
  input         io_enq_valid,
  input  [3:0]  io_enq_bits_group,
                io_enq_bits_columns,
  input  [31:0] io_enq_bits_epoch,
  output        io_deq_valid,
  output [3:0]  io_deq_bits_group,
                io_deq_bits_columns
);

  wire [7:0] _ram_ext_R0_data;
  reg        wrap;
  reg        wrap_1;
  reg        maybe_full;
  wire       ptr_match = wrap == wrap_1;
  wire       empty = ptr_match & ~maybe_full;
  wire       full = ptr_match & maybe_full;
  wire       do_enq = ~full & io_enq_valid;
  always @(posedge clock) begin
    if (reset) begin
      wrap <= 1'h0;
      wrap_1 <= 1'h0;
      maybe_full <= 1'h0;
    end
    else begin
      if (do_enq)
        wrap <= wrap - 1'h1;
      if (~empty)
        wrap_1 <= wrap_1 - 1'h1;
      if (~(do_enq == ~empty))
        maybe_full <= do_enq;
    end
  end // always @(posedge)
  ram_2x8 ram_ext (
    .R0_addr (wrap_1),
    .R0_en   (1'h1),
    .R0_clk  (clock),
    .R0_data (_ram_ext_R0_data),
    .W0_addr (wrap),
    .W0_en   (do_enq),
    .W0_clk  (clock),
    .W0_data ({io_enq_bits_columns, io_enq_bits_group})
  );
  assign io_enq_ready = ~full;
  assign io_deq_valid = ~empty;
  assign io_deq_bits_group = _ram_ext_R0_data[3:0];
  assign io_deq_bits_columns = _ram_ext_R0_data[7:4];
endmodule

// VCS coverage exclude_file
module ram_2x154(
  input          R0_addr,
                 R0_en,
                 R0_clk,
  output [153:0] R0_data,
  input          W0_addr,
                 W0_en,
                 W0_clk,
  input  [153:0] W0_data
);

  reg [153:0] Memory[0:1];
  always @(posedge W0_clk) begin
    if (W0_en & 1'h1)
      Memory[W0_addr] <= W0_data;
  end // always @(posedge)
  assign R0_data = R0_en ? Memory[R0_addr] : 154'bx;
endmodule

module Queue2_BankWrite(
  input          clock,
                 reset,
  output         io_enq_ready,
  input          io_enq_valid,
  input  [9:0]   io_enq_bits_address,
  input  [127:0] io_enq_bits_data,
  input          io_deq_ready,
  output         io_deq_valid,
  output [9:0]   io_deq_bits_address,
  output [127:0] io_deq_bits_data,
  output [15:0]  io_deq_bits_mask
);

  wire [153:0] _ram_ext_R0_data;
  reg          wrap;
  reg          wrap_1;
  reg          maybe_full;
  wire         ptr_match = wrap == wrap_1;
  wire         empty = ptr_match & ~maybe_full;
  wire         full = ptr_match & maybe_full;
  wire         do_enq = ~full & io_enq_valid;
  always @(posedge clock) begin
    if (reset) begin
      wrap <= 1'h0;
      wrap_1 <= 1'h0;
      maybe_full <= 1'h0;
    end
    else begin
      automatic logic do_deq = io_deq_ready & ~empty;
      if (do_enq)
        wrap <= wrap - 1'h1;
      if (do_deq)
        wrap_1 <= wrap_1 - 1'h1;
      if (~(do_enq == do_deq))
        maybe_full <= do_enq;
    end
  end // always @(posedge)
  ram_2x154 ram_ext (
    .R0_addr (wrap_1),
    .R0_en   (1'h1),
    .R0_clk  (clock),
    .R0_data (_ram_ext_R0_data),
    .W0_addr (wrap),
    .W0_en   (do_enq),
    .W0_clk  (clock),
    .W0_data ({16'hFFFF, io_enq_bits_data, io_enq_bits_address})
  );
  assign io_enq_ready = ~full;
  assign io_deq_valid = ~empty;
  assign io_deq_bits_address = _ram_ext_R0_data[9:0];
  assign io_deq_bits_data = _ram_ext_R0_data[137:10];
  assign io_deq_bits_mask = _ram_ext_R0_data[153:138];
endmodule

