  input  [3:0] R0_addr,
  input        R0_en,
               R0_clk,
  output [8:0] R0_data,
  input  [3:0] W0_addr,
  input        W0_en,
               W0_clk,
  input  [8:0] W0_data
);

  reg [8:0] Memory[0:10];
  always @(posedge W0_clk) begin
    if (W0_en & 1'h1)
      Memory[W0_addr] <= W0_data;
  end // always @(posedge)
  assign R0_data = R0_en ? Memory[R0_addr] : 9'bx;
endmodule

module RegisteredTagQueue_1(
  input        clock,
               reset,
  output       io_enq_ready,
  input        io_enq_valid,
  input  [8:0] io_enq_bits,
  input        io_deq_ready,
  output       io_deq_valid,
  output [8:0] io_deq_bits
);

  wire [8:0] _tail_ext_R0_data;
  reg  [8:0] head;
  reg  [3:0] readPointer;
  reg  [3:0] writePointer;
  reg  [3:0] occupancy;
  reg        room;
  reg        present;
  wire       put = room & io_enq_valid;
  wire       take = io_deq_ready & present;
  wire       directHead = put & (~(|occupancy) | take & occupancy == 4'h1);
  wire       tailPut = put & ~directHead;
  wire       tailTake = take & (|(occupancy[3:1]));
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      if (~reset & room != (occupancy[3:2] != 2'h3)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed\n    at RegisteredTagQueue.scala:63 assert(room.get === (occupancy < entries.U))\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (~reset & present != (|occupancy)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed\n    at RegisteredTagQueue.scala:64 assert(present.get === (occupancy =/= 0.U))\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (~reset & occupancy > 4'hC) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed\n    at RegisteredTagQueue.scala:67 assert(occupancy <= entries.U)\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (~reset & ~(readPointer < 4'hB & writePointer < 4'hB)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed\n    at RegisteredTagQueue.scala:68 assert(readPointer < tailEntries.U && writePointer < tailEntries.U)\n");
        if (`STOP_COND_)
          $fatal;
      end
    end // always @(posedge)
  `endif // not def SYNTHESIS
  always @(posedge clock) begin
    if (directHead)
      head <= io_enq_bits;
    else if (tailTake)
      head <= _tail_ext_R0_data;
    if (reset) begin
      readPointer <= 4'h0;
      writePointer <= 4'h0;
      occupancy <= 4'h0;
      room <= 1'h1;
      present <= 1'h0;
    end
    else begin
      if (tailTake)
        readPointer <= readPointer == 4'hA ? 4'h0 : readPointer + 4'h1;
      if (tailPut)
        writePointer <= writePointer == 4'hA ? 4'h0 : writePointer + 4'h1;
      if (~(put == take)) begin
        occupancy <= put ? occupancy + 4'h1 : occupancy - 4'h1;
        room <= take | occupancy != 4'hB;
        present <= put | occupancy != 4'h1;
      end
    end
  end // always @(posedge)
  tail_11x9 tail_ext (
    .R0_addr (readPointer),
    .R0_en   (~directHead & tailTake),
    .R0_clk  (clock),
    .R0_data (_tail_ext_R0_data),
    .W0_addr (writePointer),
    .W0_en   (tailPut),
    .W0_clk  (clock),
    .W0_data (io_enq_bits)
  );
  assign io_enq_ready = room;
  assign io_deq_valid = present;
  assign io_deq_bits = head;
endmodule

module StateRowTagQueue(
  input        clock,
               reset,
  output       io_enq_ready,
  input        io_enq_valid,
  input  [7:0] io_enq_bits,
  input        io_deq_ready,
  output       io_deq_valid,
  output [7:0] io_deq_bits,
  input  [7:0] io_keyColumns,
  output       io_withinRange
);

  wire       _queue_io_deq_valid;
  wire [8:0] _queue_io_deq_bits;
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      if (_queue_io_deq_valid & ~reset
          & _queue_io_deq_bits[8] != (_queue_io_deq_bits[7:0] < io_keyColumns)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: H row range qualification must remain valid for its owning command\n    at StateRowTagQueue.scala:34 assert(\n");
        if (`STOP_COND_)
          $fatal;
      end
    end // always @(posedge)
  `endif // not def SYNTHESIS
  RegisteredTagQueue_1 queue (
    .clock        (clock),
    .reset        (reset),
    .io_enq_ready (io_enq_ready),
    .io_enq_valid (io_enq_valid),
    .io_enq_bits  ({io_enq_bits < io_keyColumns, io_enq_bits}),
    .io_deq_ready (io_deq_ready),
    .io_deq_valid (_queue_io_deq_valid),
    .io_deq_bits  (_queue_io_deq_bits)
  );
  assign io_deq_valid = _queue_io_deq_valid;
  assign io_deq_bits = _queue_io_deq_bits[7:0];
  assign io_withinRange = _queue_io_deq_bits[8];
endmodule

