  reg         acceptedEpoch_23;
  wire [23:0] granted =
    {io_inRequest & io_needed[23] & acceptedEpoch_23 == epoch,
     io_inRequest & io_needed[22] & acceptedEpoch_22 == epoch,
     io_inRequest & io_needed[21] & acceptedEpoch_21 == epoch,
     io_inRequest & io_needed[20] & acceptedEpoch_20 == epoch,
     io_inRequest & io_needed[19] & acceptedEpoch_19 == epoch,
