     io_inRequest & io_needed[1] & acceptedEpoch_1 == epoch,
     io_inRequest & io_needed[0] & acceptedEpoch_0 == epoch};
  wire        io_complete_0 =
    io_offer & ((granted | io_accepted) & io_needed) == io_needed;
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      if (~reset & ~(~io_offer | io_inRequest)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: bank offer requires a live gather\n    at LocalBankGrants.scala:40 assert(!io.offer || io.inRequest, \"bank offer requires a live gather\")\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (~reset & (|(io_accepted & ~io_needed))) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: an unneeded bank was accepted\n    at LocalBankGrants.scala:41 assert(!(io.accepted & ~io.needed).orR, \"an unneeded bank was accepted\")\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (~reset & (|(io_accepted & granted))) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: bank accepted the same gather twice\n    at LocalBankGrants.scala:42 assert(!(io.accepted & granted).orR, \"bank accepted the same gather twice\")\n");
        if (`STOP_COND_)
