  assign io_in_1_ready = (ctrl_validMask_grantMask_1 | ~_ctrl_T_3) & io_out_ready;
  assign io_in_2_ready =
    (~ctrl_validMask_1 & ~(ctrl_validMask_grantMask_lastGrant[1]) | ~_ctrl_T_4)
    & io_out_ready;
  assign io_in_3_ready =
    (~_ctrl_T_1 & ctrl_validMask_grantMask_3 | ~(_ctrl_T_4 | io_in_2_valid))
    & io_out_ready;
  assign io_out_valid = io_out_valid_0;
  assign io_out_bits_key = _GEN_0[io_chosen_choice];
  assign io_out_bits_values_0 = _GEN_1[io_chosen_choice];
  assign io_out_bits_values_1 = _GEN_2[io_chosen_choice];
  assign io_out_bits_values_2 = _GEN_3[io_chosen_choice];
  assign io_out_bits_values_3 = _GEN_4[io_chosen_choice];
  assign io_out_bits_values_4 = _GEN_5[io_chosen_choice];
  assign io_out_bits_values_5 = _GEN_6[io_chosen_choice];
  assign io_out_bits_values_6 = _GEN_7[io_chosen_choice];
  assign io_out_bits_values_7 = _GEN_8[io_chosen_choice];
  assign io_out_bits_values_8 = _GEN_9[io_chosen_choice];
  assign io_out_bits_values_9 = _GEN_10[io_chosen_choice];
  assign io_out_bits_values_10 = _GEN_11[io_chosen_choice];
  assign io_out_bits_values_11 = _GEN_12[io_chosen_choice];
  assign io_out_bits_values_12 = _GEN_13[io_chosen_choice];
  assign io_out_bits_values_13 = _GEN_14[io_chosen_choice];
  assign io_out_bits_values_14 = _GEN_15[io_chosen_choice];
  assign io_out_bits_values_15 = _GEN_16[io_chosen_choice];
  assign io_chosen = io_chosen_choice;
endmodule

