module QueuedReadArbiter(
  input          clock,
                 reset,
  output         io_request_0_ready,
  input          io_request_0_valid,
  input  [9:0]   io_request_0_bits,
  output         io_request_1_ready,
  input          io_request_1_valid,
  input  [9:0]   io_request_1_bits,
  input          io_response_0_ready,
  output         io_response_0_valid,
  output [127:0] io_response_0_bits,
  input          io_response_1_ready,
  output         io_response_1_valid,
  output [127:0] io_response_1_bits,
  input          io_read_ready,
  output         io_read_valid,
  output [9:0]   io_read_bits,
  output         io_returned_ready,
  input          io_returned_valid,
  input  [127:0] io_returned_bits,
  input          io_shared
);

  wire       io_returned_ready_0;
  wire       _q_io_enq_ready;
  wire [1:0] _q_io_count;
  wire       _owners_io_enq_ready;
  wire       _owners_io_deq_valid;
  wire       _owners_io_deq_bits;
  wire       _arb_io_in_0_ready;
  wire       _arb_io_in_1_ready;
  wire       _arb_io_out_valid;
  wire [9:0] _arb_io_out_bits;
  wire       _arb_io_chosen;
  wire       _requests_1_io_deq_valid;
  wire [9:0] _requests_1_io_deq_bits;
  wire       _requests_0_io_enq_ready;
  wire       _requests_0_io_deq_valid;
  wire [9:0] _requests_0_io_deq_bits;
  wire       bypass = ~io_shared & ~_requests_0_io_deq_valid & ~_requests_1_io_deq_valid;
  wire       io_read_valid_0 =
    (bypass ? io_request_0_valid : _arb_io_out_valid) & _owners_io_enq_ready;
  wire       owners_io_enq_valid = io_read_ready & io_read_valid_0;
  wire       _q_io_enq_valid_T = io_returned_valid & _owners_io_deq_valid;
  reg  [1:0] pending;
  wire [2:0] _credit_T = {1'h0, _q_io_count} + {1'h0, pending};
  wire       credit = _credit_T < 3'h2;
  wire       q_io_enq_valid = _q_io_enq_valid_T & _owners_io_deq_bits;
  assign io_returned_ready_0 =
    _owners_io_deq_bits
      ? _owners_io_deq_valid & _q_io_enq_ready
      : _owners_io_deq_valid
        & (_owners_io_deq_bits ? io_response_1_ready : io_response_0_ready);
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      if (q_io_enq_valid & ~reset & ~(_q_io_enq_ready & (|pending))) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed\n    at QueuedReadArbiter.scala:78 when(q.io.enq.valid) { assert(q.io.enq.ready && pending =/= 0.U) }\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (~reset & _credit_T > 3'h2) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed\n    at QueuedReadArbiter.scala:79 assert((q.io.count +& pending) <= responseDepth.U)\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (io_returned_valid & ~reset & ~_owners_io_deq_valid) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed\n    at QueuedReadArbiter.scala:87 when(io.returned.valid) { assert(owners.io.deq.valid) }\n");
        if (`STOP_COND_)
          $fatal;
      end
    end // always @(posedge)
  `endif // not def SYNTHESIS
  always @(posedge clock) begin
    if (reset)
      pending <= 2'h0;
    else begin
      automatic logic issued;
      issued = owners_io_enq_valid & ~bypass & _arb_io_chosen;
      if (~(issued == (_q_io_enq_ready & q_io_enq_valid)))
        pending <= issued ? pending + 2'h1 : pending - 2'h1;
    end
  end // always @(posedge)
  Queue2_UInt10 requests_0 (
    .clock        (clock),
    .reset        (reset),
    .io_enq_ready (_requests_0_io_enq_ready),
    .io_enq_valid (~bypass & io_request_0_valid),
    .io_enq_bits  (io_request_0_bits),
    .io_deq_ready (_arb_io_in_0_ready),
    .io_deq_valid (_requests_0_io_deq_valid),
    .io_deq_bits  (_requests_0_io_deq_bits)
  );
  Queue2_UInt10 requests_1 (
    .clock        (clock),
    .reset        (reset),
    .io_enq_ready (io_request_1_ready),
    .io_enq_valid (io_request_1_valid),
    .io_enq_bits  (io_request_1_bits),
    .io_deq_ready (_arb_io_in_1_ready & credit),
    .io_deq_valid (_requests_1_io_deq_valid),
    .io_deq_bits  (_requests_1_io_deq_bits)
  );
  RRArbiter_59 arb (
    .clock         (clock),
    .io_in_0_ready (_arb_io_in_0_ready),
    .io_in_0_valid (_requests_0_io_deq_valid),
    .io_in_0_bits  (_requests_0_io_deq_bits),
    .io_in_1_ready (_arb_io_in_1_ready),
    .io_in_1_valid (_requests_1_io_deq_valid & credit),
    .io_in_1_bits  (_requests_1_io_deq_bits),
    .io_out_ready  (io_read_ready & _owners_io_enq_ready & ~bypass),
    .io_out_valid  (_arb_io_out_valid),
    .io_out_bits   (_arb_io_out_bits),
    .io_chosen     (_arb_io_chosen)
  );
  Queue2_UInt1 owners (
    .clock        (clock),
    .reset        (reset),
    .io_enq_ready (_owners_io_enq_ready),
    .io_enq_valid (owners_io_enq_valid),
    .io_enq_bits  (~bypass & _arb_io_chosen),
    .io_deq_ready (io_returned_ready_0 & io_returned_valid),
    .io_deq_valid (_owners_io_deq_valid),
    .io_deq_bits  (_owners_io_deq_bits)
  );
  Queue2_UInt128 q (
    .clock        (clock),
    .reset        (reset),
    .io_enq_ready (_q_io_enq_ready),
    .io_enq_valid (q_io_enq_valid),
    .io_enq_bits  (io_returned_bits),
    .io_deq_ready (io_response_1_ready),
    .io_deq_valid (io_response_1_valid),
    .io_deq_bits  (io_response_1_bits),
    .io_count     (_q_io_count)
  );
  assign io_request_0_ready =
    bypass ? io_read_ready & _owners_io_enq_ready : _requests_0_io_enq_ready;
  assign io_response_0_valid = _q_io_enq_valid_T & ~_owners_io_deq_bits;
  assign io_response_0_bits = io_returned_bits;
  assign io_read_valid = io_read_valid_0;
  assign io_read_bits = bypass ? io_request_0_bits : _arb_io_out_bits;
  assign io_returned_ready = io_returned_ready_0;
endmodule

