      : io_p_mantissa[26] ? {io_p_mantissa[26:11], 8'h0} : {io_p_mantissa[25:11], 9'h0};
  wire [23:0] cMantissa = c_isZero ? 24'h0 : {1'h1, io_c[22:0]};
  wire [9:0]  _exponentDelta_T_1 = {_c_exp_T_1[8], _c_exp_T_1} - _productExponent_T_1;
  wire        cLargest = ~c_isZero & (io_p_zero | $signed(_exponentDelta_T_1) > -10'sh1);
  wire [9:0]  distance =
    $signed(_exponentDelta_T_1) < 10'sh0
      ? 10'h0 - _exponentDelta_T_1
      : _exponentDelta_T_1;
  wire        io_out_subtract_0 = io_c[31] ^ io_p_sign;
  wire        bothZero = c_isZero & io_p_zero;
  wire        nan =
    io_p_nan | (&(io_c[30:23])) & (|(io_c[22:0])) | c_isInf & io_p_inf & io_out_subtract_0
    | io_p_zero & io_p_inf;
  wire        _io_out_flags_inf_T_1 = c_isInf | io_p_inf;
  ShiftRightJam_65 shiftRightJam (
    .io_in     ({cLargest ? productMantissa : cMantissa, 3'h0}),
    .io_shamt  (distance > 10'h1A ? 5'h1B : distance[4:0]),
    .io_out    (_shiftRightJam_io_out),
    .io_sticky (_shiftRightJam_io_sticky)
  );
  assign io_out_large = cLargest ? cMantissa : productMantissa;
  assign io_out_small =
    {_shiftRightJam_io_out[26:1], _shiftRightJam_io_out[0] | _shiftRightJam_io_sticky};
  assign io_out_subtract = io_out_subtract_0;
  assign io_out_flags_exponent =
    cLargest
      ? {{2{_c_exp_T_1[8]}}, _c_exp_T_1}
      : {_productExponent_T_1[9], _productExponent_T_1};
  assign io_out_flags_sign =
    c_isInf
      ? io_c[31]
      : io_p_inf
          ? io_p_sign
          : bothZero ? io_c[31] & io_p_sign : cLargest ? io_c[31] : io_p_sign;
  assign io_out_flags_cancellationSign = ~(_io_out_flags_inf_T_1 | bothZero);
  assign io_out_flags_bothZero = bothZero;
  assign io_out_flags_inf = ~nan & _io_out_flags_inf_T_1;
  assign io_out_flags_nan = nan;
endmodule

module NarrowFmaAddStage(
  input  [23:0] io_in_large,
  input  [26:0] io_in_small,
