         _propagate_T[16] ^ ~_GEN_31,
         _propagate_T[15] ^ ~_GEN_56,
         _propagate_T[14] ^ ~_GEN_41,
         _propagate_T[13] ^ ~_GEN_55,
         _propagate_T[12] ^ ~_GEN_35,
