      : {_propagate_T[27] ^ (_GEN_62 | _propagate_T[26] & _GEN_50 & io_in_subtract),
         _propagate_T[26] ^ (_GEN_44 | _GEN_50 & io_in_subtract),
         _propagate_T[25] ^ (_GEN_61 | _propagate_T[24] & _GEN_34 & io_in_subtract),
         _propagate_T[24] ^ (_GEN_33 | _GEN_34 & io_in_subtract),
         _propagate_T[23] ^ (_GEN_60 | _propagate_T[22] & _GEN_49 & io_in_subtract),
         _propagate_T[22] ^ (_GEN_43 | _GEN_49 & io_in_subtract),
         _propagate_T[21] ^ (_GEN_59 | _propagate_T[20] & _GEN_38 & io_in_subtract),
         _propagate_T[20] ^ (_GEN_36 | _GEN_38 & io_in_subtract),
         _propagate_T[19] ^ (_GEN_58 | _propagate_T[18] & _GEN_48 & io_in_subtract),
         _propagate_T[18] ^ (_GEN_42 | _GEN_48 & io_in_subtract),
         _propagate_T[17] ^ (_GEN_57 | _propagate_T[16] & _GEN_32 & io_in_subtract),
