module NarrowFmaNormalizeStage(
  input  [27:0] io_in_magnitude,
  input  [10:0] io_in_flags_exponent,
  input         io_in_flags_sign,
                io_in_flags_cancellationSign,
                io_in_flags_bothZero,
                io_in_flags_inf,
                io_in_flags_nan,
  output        io_out_isZero,
                io_out_isInf,
                io_out_isNaN,
                io_out_sign,
  output [10:0] io_out_exp,
  output [25:0] io_out_mantissa
);

  wire [4:0]  leadingZeros =
    io_in_magnitude[27]
      ? 5'h0
      : io_in_magnitude[26]
          ? 5'h1
          : io_in_magnitude[25]
              ? 5'h2
              : io_in_magnitude[24]
                  ? 5'h3
                  : io_in_magnitude[23]
                      ? 5'h4
                      : io_in_magnitude[22]
                          ? 5'h5
                          : io_in_magnitude[21]
                              ? 5'h6
                              : io_in_magnitude[20]
                                  ? 5'h7
                                  : io_in_magnitude[19]
                                      ? 5'h8
                                      : io_in_magnitude[18]
                                          ? 5'h9
                                          : io_in_magnitude[17]
                                              ? 5'hA
                                              : io_in_magnitude[16]
                                                  ? 5'hB
                                                  : io_in_magnitude[15]
                                                      ? 5'hC
                                                      : io_in_magnitude[14]
                                                          ? 5'hD
                                                          : io_in_magnitude[13]
                                                              ? 5'hE
                                                              : io_in_magnitude[12]
                                                                  ? 5'hF
                                                                  : io_in_magnitude[11]
                                                                      ? 5'h10
                                                                      : io_in_magnitude[10]
                                                                          ? 5'h11
                                                                          : io_in_magnitude[9]
                                                                              ? 5'h12
                                                                              : io_in_magnitude[8]
                                                                                  ? 5'h13
                                                                                  : io_in_magnitude[7]
                                                                                      ? 5'h14
                                                                                      : io_in_magnitude[6]
                                                                                          ? 5'h15
                                                                                          : io_in_magnitude[5]
                                                                                              ? 5'h16
                                                                                              : io_in_magnitude[4]
                                                                                                  ? 5'h17
                                                                                                  : io_in_magnitude[3]
                                                                                                      ? 5'h18
                                                                                                      : io_in_magnitude[2]
                                                                                                          ? 5'h19
                                                                                                          : {4'hD,
                                                                                                             ~(io_in_magnitude[1])};
  wire [58:0] _normalized_T = {31'h0, io_in_magnitude} << leadingZeros;
  wire        zero = io_in_magnitude == 28'h0;
  assign io_out_isZero = io_in_flags_bothZero | zero;
  assign io_out_isInf = io_in_flags_inf;
  assign io_out_isNaN = io_in_flags_nan;
  assign io_out_sign = ~(io_in_flags_cancellationSign & zero) & io_in_flags_sign;
  assign io_out_exp = io_in_flags_exponent + 11'h1 - {6'h0, leadingZeros};
  assign io_out_mantissa = {_normalized_T[27:3], |(_normalized_T[2:0])};
endmodule

module NarrowFmaDatapath(
  input         clock,
                io_advance,
  input  [15:0] io_a,
                io_b,
  input  [31:0] io_lateC,
  output [31:0] io_result
);

  wire        _normalize_io_out_isZero;
  wire        _normalize_io_out_isInf;
  wire        _normalize_io_out_isNaN;
  wire        _normalize_io_out_sign;
  wire [10:0] _normalize_io_out_exp;
  wire [25:0] _normalize_io_out_mantissa;
  wire [27:0] _add_io_out_magnitude;
  wire [10:0] _add_io_out_flags_exponent;
  wire        _add_io_out_flags_sign;
  wire        _add_io_out_flags_cancellationSign;
  wire        _add_io_out_flags_bothZero;
  wire        _add_io_out_flags_inf;
  wire        _add_io_out_flags_nan;
  wire [23:0] _align_io_out_large;
  wire [26:0] _align_io_out_small;
  wire        _align_io_out_subtract;
  wire [10:0] _align_io_out_flags_exponent;
  wire        _align_io_out_flags_sign;
  wire        _align_io_out_flags_cancellationSign;
  wire        _align_io_out_flags_bothZero;
  wire        _align_io_out_flags_inf;
  wire        _align_io_out_flags_nan;
  wire [26:0] _product_io_out_mantissa;
  wire [9:0]  _product_io_out_exp;
  wire        _product_io_out_sign;
  wire        _product_io_out_zero;
  wire        _product_io_out_inf;
  wire        _product_io_out_nan;
  reg  [26:0] pr_mantissa;
  reg  [9:0]  pr_exp;
  reg         pr_sign;
  reg         pr_zero;
  reg         pr_inf;
  reg         pr_nan;
  reg  [23:0] ar_large;
  reg  [26:0] ar_small;
  reg         ar_subtract;
  reg  [10:0] ar_flags_exponent;
  reg         ar_flags_sign;
  reg         ar_flags_cancellationSign;
  reg         ar_flags_bothZero;
  reg         ar_flags_inf;
  reg         ar_flags_nan;
  reg  [27:0] sr_magnitude;
  reg  [10:0] sr_flags_exponent;
  reg         sr_flags_sign;
  reg         sr_flags_cancellationSign;
  reg         sr_flags_bothZero;
  reg         sr_flags_inf;
  reg         sr_flags_nan;
  reg         nr_isZero;
  reg         nr_isInf;
  reg         nr_isNaN;
  reg         nr_sign;
  reg  [10:0] nr_exp;
  reg  [25:0] nr_mantissa;
  wire        io_result_up = nr_mantissa[1] & (nr_mantissa[0] | nr_mantissa[2]);
  wire        io_result_carry = (&(nr_mantissa[24:2])) & io_result_up;
  wire        io_result_overflow =
    $signed(nr_exp) > 11'sh7F | nr_exp == 11'h7F & io_result_carry;
  wire        io_result_underflow =
    $signed(nr_exp) < -11'sh7F | nr_exp == 11'h781 & ~io_result_carry;
  always @(posedge clock) begin
    if (io_advance) begin
      pr_mantissa <= _product_io_out_mantissa;
      pr_exp <= _product_io_out_exp;
      pr_sign <= _product_io_out_sign;
      pr_zero <= _product_io_out_zero;
      pr_inf <= _product_io_out_inf;
      pr_nan <= _product_io_out_nan;
      ar_large <= _align_io_out_large;
      ar_small <= _align_io_out_small;
      ar_subtract <= _align_io_out_subtract;
      ar_flags_exponent <= _align_io_out_flags_exponent;
      ar_flags_sign <= _align_io_out_flags_sign;
      ar_flags_cancellationSign <= _align_io_out_flags_cancellationSign;
      ar_flags_bothZero <= _align_io_out_flags_bothZero;
      ar_flags_inf <= _align_io_out_flags_inf;
      ar_flags_nan <= _align_io_out_flags_nan;
      sr_magnitude <= _add_io_out_magnitude;
      sr_flags_exponent <= _add_io_out_flags_exponent;
      sr_flags_sign <= _add_io_out_flags_sign;
      sr_flags_cancellationSign <= _add_io_out_flags_cancellationSign;
      sr_flags_bothZero <= _add_io_out_flags_bothZero;
      sr_flags_inf <= _add_io_out_flags_inf;
      sr_flags_nan <= _add_io_out_flags_nan;
      nr_isZero <= _normalize_io_out_isZero;
      nr_isInf <= _normalize_io_out_isInf;
      nr_isNaN <= _normalize_io_out_isNaN;
      nr_sign <= _normalize_io_out_sign;
      nr_exp <= _normalize_io_out_exp;
      nr_mantissa <= _normalize_io_out_mantissa;
    end
  end // always @(posedge)
  FmaProductStage product (
    .io_a            (io_a),
    .io_b            (io_b),
    .io_out_mantissa (_product_io_out_mantissa),
    .io_out_exp      (_product_io_out_exp),
    .io_out_sign     (_product_io_out_sign),
    .io_out_zero     (_product_io_out_zero),
    .io_out_inf      (_product_io_out_inf),
    .io_out_nan      (_product_io_out_nan)
  );
  NarrowFmaAlignStage align (
    .io_p_mantissa                 (pr_mantissa),
    .io_p_exp                      (pr_exp),
    .io_p_sign                     (pr_sign),
    .io_p_zero                     (pr_zero),
    .io_p_inf                      (pr_inf),
    .io_p_nan                      (pr_nan),
    .io_c                          (io_lateC),
    .io_out_large                  (_align_io_out_large),
    .io_out_small                  (_align_io_out_small),
    .io_out_subtract               (_align_io_out_subtract),
    .io_out_flags_exponent         (_align_io_out_flags_exponent),
    .io_out_flags_sign             (_align_io_out_flags_sign),
    .io_out_flags_cancellationSign (_align_io_out_flags_cancellationSign),
    .io_out_flags_bothZero         (_align_io_out_flags_bothZero),
    .io_out_flags_inf              (_align_io_out_flags_inf),
    .io_out_flags_nan              (_align_io_out_flags_nan)
  );
  NarrowFmaAddStage add (
    .io_in_large                   (ar_large),
    .io_in_small                   (ar_small),
