module RegisteredInstructionQueue(
  input          clock,
                 reset,
  output         io_enq_ready,
  input          io_enq_valid,
  input  [127:0] io_enq_bits,
  input          io_deq_ready,
  output         io_deq_valid,
  output [127:0] io_deq_bits,
  output         io_staticIllegal
);

  wire         enqueuedIllegal_legal;
  wire         _tailIllegal_ext_R0_data;
  wire [127:0] _tail_ext_R0_data;
  reg  [127:0] head;
