  wire         take = io_deq_ready & (|occupancy);
  wire         directHead = put & (occupancy == 3'h0 | take & occupancy == 3'h1);
  wire         tailTake = take & (|(occupancy[2:1]));
  wire         _GEN = ~directHead & tailTake;
