    enqueuedIllegal_dimensions & _enqueuedIllegal_release_T;
  assign enqueuedIllegal_legal =
    io_enq_bits[7:0] < 8'h5 | io_enq_bits[7:0] == 8'h21 & enqueuedIllegal_chunk
    | io_enq_bits[7:0] == 8'h22 & enqueuedIllegal_chunk & ~(io_enq_bits[50])
    & ~(io_enq_bits[49]) | io_enq_bits[7:0] == 8'h23 & _enqueuedIllegal_release_T
    & ~(io_enq_bits[50]) & ~(io_enq_bits[49]) & io_enq_bits[47:32] == 16'h0
    | (io_enq_bits[7:0] == 8'h24 | io_enq_bits[7:0] == 8'h25) & enqueuedIllegal_dimensions
    & io_enq_bits[127:64] == 64'h0 & io_enq_bits[15:12] == 4'h0 & (|(io_enq_bits[54:48]))
    & io_enq_bits[54:48] < 7'h41 & {1'h0, io_enq_bits[63:55]}
    + {1'h0, io_enq_bits[39:32], 1'h0} < 10'h201;
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      automatic logic dimensions =
        (|(head[39:32])) & head[39:32] < 8'h81 & (|(head[47:40])) & head[47:40] < 8'h81;
      automatic logic _release_T = {head[127:51], head[15:12]} == 81'h0;
      automatic logic chunk = dimensions & _release_T;
      if ((|occupancy) & ~reset
          & headIllegal != ~(head[7:0] < 8'h5 | head[7:0] == 8'h21 & chunk
                             | head[7:0] == 8'h22 & chunk & ~(head[50]) & ~(head[49])
                             | head[7:0] == 8'h23 & _release_T & ~(head[50]) & ~(head[49])
                             & head[47:32] == 16'h0
                             | (head[7:0] == 8'h24 | head[7:0] == 8'h25) & dimensions
                             & head[127:64] == 64'h0 & head[15:12] == 4'h0
                             & (|(head[54:48])) & head[54:48] < 7'h41
                             & {1'h0, head[63:55]}
                             + {1'h0, head[39:32], 1'h0} < 10'h201)) begin
