    if (directHead) begin
      head <= io_enq_bits;
      headIllegal <= ~enqueuedIllegal_legal;
    end
    else if (tailTake) begin
      head <= _tail_ext_R0_data;
      headIllegal <= _tailIllegal_ext_R0_data;
    end
