      if (io_eligible & checked & ~reset & checkedBad != io_bad) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: GDN legality must remain stable while its confirmed head is resident\n    at GdnCommandCheck.scala:32 assert(\n");
