module ram_2x30(
  input         R0_addr,
                R0_en,
                R0_clk,
  output [29:0] R0_data,
  input         W0_addr,
                W0_en,
                W0_clk,
  input  [29:0] W0_data
);

  reg [29:0] Memory[0:1];
  always @(posedge W0_clk) begin
    if (W0_en & 1'h1)
      Memory[W0_addr] <= W0_data;
  end // always @(posedge)
  assign R0_data = R0_en ? Memory[R0_addr] : 30'bx;
endmodule

module Queue2_SystemCompletion(
  input         clock,
                reset,
  output        io_enq_ready,
  input         io_enq_valid,
  input  [15:0] io_enq_bits_tag,
  input  [7:0]  io_enq_bits_opcode,
  input         io_enq_bits_error,
                io_deq_ready,
  output        io_deq_valid,
  output [1:0]  io_deq_bits_tile,
                io_deq_bits_port,
  output        io_deq_bits_dma,
  output [15:0] io_deq_bits_tag,
  output [7:0]  io_deq_bits_opcode,
  output        io_deq_bits_error
);

  wire [29:0] _ram_ext_R0_data;
  reg         wrap;
  reg         wrap_1;
  reg         maybe_full;
  wire        ptr_match = wrap == wrap_1;
  wire        empty = ptr_match & ~maybe_full;
  wire        full = ptr_match & maybe_full;
  wire        do_enq = ~full & io_enq_valid;
  always @(posedge clock) begin
    if (reset) begin
      wrap <= 1'h0;
      wrap_1 <= 1'h0;
      maybe_full <= 1'h0;
    end
    else begin
      automatic logic do_deq = io_deq_ready & ~empty;
      if (do_enq)
        wrap <= wrap - 1'h1;
      if (do_deq)
        wrap_1 <= wrap_1 - 1'h1;
      if (~(do_enq == do_deq))
        maybe_full <= do_enq;
    end
