  reg  [5:0] deq_ptr_value;
  reg        maybe_full;
  wire       ptr_match = enq_ptr_value == deq_ptr_value;
  wire       empty = ptr_match & ~maybe_full;
  wire       full = ptr_match & maybe_full;
  wire       do_enq = ~full & io_enq_valid;
  always @(posedge clock) begin
    if (reset) begin
      enq_ptr_value <= 6'h0;
      deq_ptr_value <= 6'h0;
      maybe_full <= 1'h0;
    end
    else begin
      automatic logic do_deq = io_deq_ready & ~empty;
      if (do_enq)
        enq_ptr_value <= enq_ptr_value + 6'h1;
      if (do_deq)
        deq_ptr_value <= deq_ptr_value + 6'h1;
      if (~(do_enq == do_deq))
        maybe_full <= do_enq;
    end
  end // always @(posedge)
  ram_64x32 ram_ext (
    .R0_addr (deq_ptr_value),
    .R0_en   (1'h1),
    .R0_clk  (clock),
    .R0_data (io_deq_bits),
    .W0_addr (enq_ptr_value),
    .W0_en   (do_enq),
    .W0_clk  (clock),
    .W0_data (io_enq_bits)
  );
  assign io_enq_ready = ~full;
  assign io_deq_valid = ~empty;
endmodule

module EventCounter(
  input         clock,
                reset,
  output [63:0] io_value
);

  reg [63:0] value;
  always @(posedge clock) begin
    if (reset)
      value <= 64'h0;
    else begin
      automatic logic [8:0] value_low = {1'h0, value[7:0]} + 9'h1;
      value <=
        {value[63:56] + {7'h0, value_low[8] & (&(value[55:8]))},
         value[55:48] + {7'h0, value_low[8] & (&(value[47:8]))},
         value[47:40] + {7'h0, value_low[8] & (&(value[39:8]))},
         value[39:32] + {7'h0, value_low[8] & (&(value[31:8]))},
         value[31:24] + {7'h0, value_low[8] & (&(value[23:8]))},
         value[23:16] + {7'h0, value_low[8] & (&(value[15:8]))},
         value[15:8] + {7'h0, value_low[8]},
         value_low[7:0]};
    end
  end // always @(posedge)
  assign io_value = value;
endmodule

