  output [63:0] io_value
);

  reg  [4:0]  pending_0;
  reg  [4:0]  pending_1;
  reg  [4:0]  pending_2;
  reg  [4:0]  pending_3;
  reg  [63:0] accumulated;
  wire [8:0]  visible_low =
    {1'h0, accumulated[7:0]}
    + {2'h0,
       {1'h0, {1'h0, pending_0} + {1'h0, pending_1}}
         + {1'h0, {1'h0, pending_2} + {1'h0, pending_3}}};
  wire [63:0] visible =
    {accumulated[63:56] + {7'h0, visible_low[8] & (&(accumulated[55:8]))},
     accumulated[55:48] + {7'h0, visible_low[8] & (&(accumulated[47:8]))},
     accumulated[47:40] + {7'h0, visible_low[8] & (&(accumulated[39:8]))},
     accumulated[39:32] + {7'h0, visible_low[8] & (&(accumulated[31:8]))},
     accumulated[31:24] + {7'h0, visible_low[8] & (&(accumulated[23:8]))},
     accumulated[23:16] + {7'h0, visible_low[8] & (&(accumulated[15:8]))},
     accumulated[15:8] + {7'h0, visible_low[8]},
     visible_low[7:0]};
  always @(posedge clock) begin
    if (reset) begin
      pending_0 <= 5'h0;
      pending_1 <= 5'h0;
      pending_2 <= 5'h0;
      pending_3 <= 5'h0;
      accumulated <= 64'h0;
    end
    else begin
      pending_0 <=
        {1'h0,
         {1'h0,
          {1'h0, {1'h0, io_events_0} + {1'h0, io_events_1}}
            + {1'h0, {1'h0, io_events_2} + {1'h0, io_events_3}}}
           + {1'h0,
              {1'h0, {1'h0, io_events_4} + {1'h0, io_events_5}}
                + {1'h0, {1'h0, io_events_6} + {1'h0, io_events_7}}}}
        + {1'h0,
           {1'h0,
            {1'h0, {1'h0, io_events_8} + {1'h0, io_events_9}}
              + {1'h0, {1'h0, io_events_10} + {1'h0, io_events_11}}}
             + {1'h0,
                {1'h0, {1'h0, io_events_12} + {1'h0, io_events_13}}
                  + {1'h0, {1'h0, io_events_14} + {1'h0, io_events_15}}}};
      pending_1 <=
        {1'h0,
         {1'h0,
          {1'h0, {1'h0, io_events_16} + {1'h0, io_events_17}}
            + {1'h0, {1'h0, io_events_18} + {1'h0, io_events_19}}}
           + {1'h0,
              {1'h0, {1'h0, io_events_20} + {1'h0, io_events_21}}
                + {1'h0, {1'h0, io_events_22} + {1'h0, io_events_23}}}}
        + {1'h0,
           {1'h0,
            {1'h0, {1'h0, io_events_24} + {1'h0, io_events_25}}
              + {1'h0, {1'h0, io_events_26} + {1'h0, io_events_27}}}
             + {1'h0,
                {1'h0, {1'h0, io_events_28} + {1'h0, io_events_29}}
                  + {1'h0, {1'h0, io_events_30} + {1'h0, io_events_31}}}};
      pending_2 <=
        {1'h0,
         {1'h0,
          {1'h0, {1'h0, io_events_32} + {1'h0, io_events_33}}
            + {1'h0, {1'h0, io_events_34} + {1'h0, io_events_35}}}
           + {1'h0,
              {1'h0, {1'h0, io_events_36} + {1'h0, io_events_37}}
                + {1'h0, {1'h0, io_events_38} + {1'h0, io_events_39}}}}
        + {1'h0,
           {1'h0,
            {1'h0, {1'h0, io_events_40} + {1'h0, io_events_41}}
              + {1'h0, {1'h0, io_events_42} + {1'h0, io_events_43}}}
             + {1'h0,
                {1'h0, {1'h0, io_events_44} + {1'h0, io_events_45}}
                  + {1'h0, {1'h0, io_events_46} + {1'h0, io_events_47}}}};
      pending_3 <=
        {1'h0,
         {1'h0,
          {1'h0, {1'h0, io_events_48} + {1'h0, io_events_49}}
            + {1'h0, {1'h0, io_events_50} + {1'h0, io_events_51}}}
           + {1'h0,
              {1'h0, {1'h0, io_events_52} + {1'h0, io_events_53}}
                + {1'h0, {1'h0, io_events_54} + {1'h0, io_events_55}}}}
        + {1'h0,
           {1'h0,
            {1'h0, {1'h0, io_events_56} + {1'h0, io_events_57}}
              + {1'h0, {1'h0, io_events_58} + {1'h0, io_events_59}}}
             + {1'h0,
                {1'h0, {1'h0, io_events_60} + {1'h0, io_events_61}}
                  + {1'h0, {1'h0, io_events_62} + {1'h0, io_events_63}}}};
      accumulated <= visible;
    end
  end // always @(posedge)
  assign io_value = visible;
endmodule

module GroupedDmaEventCounter(
  input         clock,
                reset,
                io_events_0,
                io_events_1,
                io_events_2,
                io_events_3,
                io_events_4,
                io_events_5,
                io_events_6,
                io_events_7,
                io_events_8,
                io_events_9,
                io_events_10,
                io_events_11,
                io_events_12,
                io_events_13,
                io_events_14,
                io_events_15,
  output [63:0] io_value
);

  reg  [3:0]  pending_0;
  reg  [3:0]  pending_1;
  reg  [63:0] accumulated;
  wire [8:0]  visible_low =
    {1'h0, accumulated[7:0]} + {4'h0, {1'h0, pending_0} + {1'h0, pending_1}};
  wire [63:0] visible =
    {accumulated[63:56] + {7'h0, visible_low[8] & (&(accumulated[55:8]))},
     accumulated[55:48] + {7'h0, visible_low[8] & (&(accumulated[47:8]))},
     accumulated[47:40] + {7'h0, visible_low[8] & (&(accumulated[39:8]))},
     accumulated[39:32] + {7'h0, visible_low[8] & (&(accumulated[31:8]))},
     accumulated[31:24] + {7'h0, visible_low[8] & (&(accumulated[23:8]))},
     accumulated[23:16] + {7'h0, visible_low[8] & (&(accumulated[15:8]))},
     accumulated[15:8] + {7'h0, visible_low[8]},
     visible_low[7:0]};
  always @(posedge clock) begin
    if (reset) begin
      pending_0 <= 4'h0;
      pending_1 <= 4'h0;
      accumulated <= 64'h0;
    end
    else begin
      pending_0 <=
        {1'h0,
         {1'h0, {1'h0, io_events_0} + {1'h0, io_events_1}}
           + {1'h0, {1'h0, io_events_2} + {1'h0, io_events_3}}}
        + {1'h0,
           {1'h0, {1'h0, io_events_4} + {1'h0, io_events_5}}
             + {1'h0, {1'h0, io_events_6} + {1'h0, io_events_7}}};
      pending_1 <=
        {1'h0,
         {1'h0, {1'h0, io_events_8} + {1'h0, io_events_9}}
           + {1'h0, {1'h0, io_events_10} + {1'h0, io_events_11}}}
        + {1'h0,
           {1'h0, {1'h0, io_events_12} + {1'h0, io_events_13}}
             + {1'h0, {1'h0, io_events_14} + {1'h0, io_events_15}}};
      accumulated <= visible;
    end
  end // always @(posedge)
  assign io_value = visible;
endmodule

// VCS coverage exclude_file
module ram_2x33(
  input         R0_addr,
                R0_en,
                R0_clk,
  output [32:0] R0_data,
  input         W0_addr,
                W0_en,
                W0_clk,
  input  [32:0] W0_data
);

  reg [32:0] Memory[0:1];
  always @(posedge W0_clk) begin
    if (W0_en & 1'h1)
      Memory[W0_addr] <= W0_data;
  end // always @(posedge)
  assign R0_data = R0_en ? Memory[R0_addr] : 33'bx;
endmodule

module Queue2_RegMapperOutput(
  input         clock,
                reset,
  output        io_enq_ready,
  input         io_enq_valid,
                io_enq_bits_read,
  input  [31:0] io_enq_bits_data,
  input         io_enq_bits_extra_extra_id,
                io_deq_ready,
  output        io_deq_valid,
                io_deq_bits_read,
  output [31:0] io_deq_bits_data
);

  wire [32:0] _ram_ext_R0_data;
  reg         wrap;
  reg         wrap_1;
  reg         maybe_full;
  wire        ptr_match = wrap == wrap_1;
  wire        empty = ptr_match & ~maybe_full;
  wire        full = ptr_match & maybe_full;
  wire        do_enq = ~full & io_enq_valid;
  always @(posedge clock) begin
    if (reset) begin
      wrap <= 1'h0;
      wrap_1 <= 1'h0;
      maybe_full <= 1'h0;
    end
    else begin
      automatic logic do_deq = io_deq_ready & ~empty;
      if (do_enq)
        wrap <= wrap - 1'h1;
      if (do_deq)
        wrap_1 <= wrap_1 - 1'h1;
      if (~(do_enq == do_deq))
        maybe_full <= do_enq;
    end
  end // always @(posedge)
  ram_2x33 ram_ext (
    .R0_addr (wrap_1),
    .R0_en   (1'h1),
    .R0_clk  (clock),
    .R0_data (_ram_ext_R0_data),
    .W0_addr (wrap),
    .W0_en   (do_enq),
    .W0_clk  (clock),
    .W0_data ({io_enq_bits_data, io_enq_bits_read})
  );
  assign io_enq_ready = ~full;
  assign io_deq_valid = ~empty;
  assign io_deq_bits_read = _ram_ext_R0_data[0];
  assign io_deq_bits_data = _ram_ext_R0_data[32:1];
endmodule

