// ----- 8< ----- FILE "./plusarg_reader.v" ----- 8< -----

// See LICENSE.SiFive for license details.

//VCS coverage exclude_file

// No default parameter values are intended, nor does IEEE 1800-2012 require them (clause A.2.4 param_assignment),
// but Incisive demands them. These default values should never be used.
module plusarg_reader #(
   parameter FORMAT="borked=%d",
   parameter WIDTH=1,
   parameter [WIDTH-1:0] DEFAULT=0
) (
   output [WIDTH-1:0] out
);

`ifdef SYNTHESIS
assign out = DEFAULT;
`else
reg [WIDTH-1:0] myplus;
assign out = myplus;

initial begin
   if (!$value$plusargs(FORMAT, myplus)) myplus = DEFAULT;
end
`endif

endmodule
// ----- 8< ----- FILE "./ScratchpadSram.sv" ----- 8< -----

// Generated by CIRCT firtool-1.75.0

module ScratchpadSram #(
    parameter DEPTH = 1024,
    parameter BYTES = 16
) (
    input clock,
    input ren,
    input wen,
    input [$clog2(DEPTH)-1:0] raddr,
    input [$clog2(DEPTH)-1:0] waddr,
    input [8*BYTES-1:0] wdata,
    input [BYTES-1:0] wmask,
    output reg [8*BYTES-1:0] rdata
);
    reg [8*BYTES-1:0] mem [0:DEPTH-1];
    integer lane;

    always @(posedge clock) begin
        if (ren) begin
            rdata <= mem[raddr];
        end
        if (wen) begin
            for (lane = 0; lane < BYTES; lane = lane + 1) begin
                if (wmask[lane]) begin
                    mem[waddr][8*lane +: 8] <= wdata[8*lane +: 8];
                end
            end
        end
    end
endmodule
// ----- 8< ----- FILE "./GenericDigitalOutIOCell.v" ----- 8< -----


`timescale 1ns/1ps
module GenericDigitalOutIOCell(
    output pad,
    input o,
    input oe
);

    assign pad = oe ? o : 1'bz;

endmodule
